    private static void insertItemsIntoCrafter(SceneBuildingUtil util, CreateSceneBuilder scene, ItemStack stack) {
        scene.world().modifyBlockEntity(util.grid().at(3, 2, 5), BlockEntity.class, be -> {
            IItemHandler handler = (IItemHandler)be.getCapability(ForgeCapabilities.ITEM_HANDLER).orElse(null);
            if (handler == null) {
                return;
            }
            ItemHandlerHelper.insertItemStacked((IItemHandler)handler, (ItemStack)stack, (boolean)false);
        });
    }
}

