import net.minecraft.world.item.Items;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.phys.AABB;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.ItemHandlerHelper;

public class RepackagerScenes {
    public static void repackager(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("repackager", "Merging packages from a request");
        scene.configureBasePlate(1, 0, 7);
        scene.setSceneOffsetY(-0.5f);
        scene.showBasePlate();
        Selection belt2 = util.select().fromTo(7, 1, 2, 6, 1, 1);
        Selection belt1 = util.select().fromTo(1, 1, 2, 4, 1, 1);
        Selection belt3 = util.select().fromTo(5, 1, 1, 5, 1, 6).add(util.select().fromTo(6, 1, 5, 6, 1, 6));
        Selection crafterCogs = util.select().fromTo(1, 1, 6, 0, 2, 6).add(util.select().position(0, 2, 5)).add(util.select().fromTo(1, 1, 7, 2, 0, 7));
        Selection crafter = util.select().fromTo(1, 2, 5, 3, 4, 5);
        Selection crafterScaff = util.select().fromTo(3, 1, 5, 1, 1, 5);
        Selection packager = util.select().fromTo(4, 1, 5, 4, 2, 5);
        BlockPos pack = util.grid().at(4, 2, 5);
        Selection packFunnel = util.select().position(5, 2, 5);
        Selection largeCog1 = util.select().position(0, 0, 2);
        Selection largeCog2 = util.select().position(8, 0, 2);
        BlockPos funnel1 = util.grid().at(4, 2, 1);
        BlockPos funnel2 = util.grid().at(6, 2, 1);
        Selection f3s = util.select().position(5, 2, 3);
        Selection f2s = util.select().position(funnel2);
        Selection f1s = util.select().position(funnel1);
        Selection barrel = util.select().position(5, 2, 1);
        BlockPos repack = util.grid().at(5, 2, 2);
        Selection repackS = util.select().fromTo(5, 2, 2, 5, 3, 2);
        Selection largeCog3 = util.select().position(6, 0, 7);
        scene.world().multiplyKineticSpeed(util.select().everywhere(), 0.5f);
        scene.idle(10);
        scene.world().showSection(crafterScaff, Direction.NORTH);
        scene.idle(3);
        scene.world().showSection(crafter, Direction.DOWN);
        scene.idle(5);
        scene.world().showSection(packager, Direction.WEST);
        scene.world().showSection(crafterCogs, Direction.EAST);
        scene.idle(5);
        scene.overlay().showText(120).text("Sometimes, it is crucial for logistical requests to arrive as a single package").attachKeyFrame().placeNearTarget().independent(130);
        scene.idle(90);
        scene.world().showSection(belt3, Direction.WEST);

