        Selection train2a = util.select().fromTo(11, 2, 3, 8, 3, 5);
        Selection train2b = util.select().fromTo(11, 2, 0, 8, 3, 2);
        for (int i = 10; i >= 0; --i) {
            scene.world().showSection(util.select().position(i, 1, 7), Direction.DOWN);
